package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.phys.Vec3;

/** Server-clock welfare, interruptible physical routines and bounded owner interactions. */
public final class TycoonCare {
    private static final String[] NAMES={"Mira","Eli","Nora","Theo","Ada","Finn","Iris","Jules","Lena","Otis","Rory","Vera","Quinn","Sam","Cleo","Arlo"};
    public static TycoonData.Resident generate(UUID id){var random=new Random(id.getMostSignificantBits()^id.getLeastSignificantBits());var n=new CompoundTag();n.putString("Name",NAMES[random.nextInt(NAMES.length)]+" "+id.toString().substring(0,8));n.putInt("Age",7+random.nextInt(6));n.putInt("Appearance",random.nextInt(32768));n.putString("Status","CANDIDATE");n.putString("Favorite",random.nextBoolean()?"minecraft:apple":"minecraft:bread");var traits=new CompoundTag();for(String key:List.of("Independence","Curiosity","Trustingness","Suspiciousness","Sensitivity","Patience","Mischief","Sociability","Activity","WorkerAptitude"))traits.putDouble(key,random.nextDouble());n.put("Traits",traits);n.putDouble("Hunger",90);n.putDouble("Thirst",90);n.putDouble("Neglect",5);n.putString("Conversion","NONE");n.put("Future",new CompoundTag());return new TycoonData.Resident(id,n);}
    public static String personality(TycoonData.Resident r){return (r.trait("Independence")>.65?"Independent":r.trait("Sociability")>.6?"Sociable":"Thoughtful")+", "+(r.trait("Curiosity")>.55?"curious":r.trait("Patience")>.5?"patient":"energetic")+"; likes "+r.n.getString("Favorite").replace("minecraft:","");}
    public static TycoonData.Resident resident(TycoonNpc actor){if(actor.getServer()==null||actor.owner==null||actor.resident==null)return null;var h=TycoonData.get(actor.getServer()).homes.get(actor.owner);return h==null?null:h.residents.get(actor.resident);}
    public static void needs(TycoonData.Resident r,int ticks,boolean comfortable){double activity=.8+r.trait("Activity")*.4;r.need("Hunger",r.need("Hunger")-ticks*.00135*activity);r.need("Thirst",r.need("Thirst")-ticks*.0018*activity);double pressure=(r.need("Hunger")<30?.001:0)+(r.need("Thirst")<30?.0016:0)+(comfortable?-.0003:.00025);r.need("Neglect",r.need("Neglect")+ticks*pressure*(.8+r.trait("Sensitivity")*.4));r.n.putBoolean("FutureAttractionEligible",r.need("Neglect")>=TycoonConfig.FUTURE.get()&&r.need("Neglect")<TycoonConfig.SEVERE.get());}
    public static void tickNpc(TycoonNpc actor){if(actor.owner==null)return;if(com.coraline.feast.GhostVictimActors.leased(actor))return;var p=TycoonOfflineCollaboration.representative(actor.getServer(),actor.owner);if(p==null){actor.getNavigation().stop();return;}TycoonScope.run(p,actor.owner,()->tickOwned(p,actor));}
    static void tickOwned(ServerPlayer p,TycoonNpc actor){if(com.coraline.feast.GhostVictimActors.leased(actor))return;if(!TycoonWorld.owner(p).equals(actor.owner))return;var h=TycoonWorld.home(p);if(TycoonWorld.busy(p)){actor.getNavigation().stop();return;}
        if(actor.staff()){staffTick(p,actor);return;}var r=h.residents.get(actor.resident);if(r==null){actor.setInvisible(true);actor.getNavigation().stop();return;}if(r.n.hasUUID("Entity")&&!r.n.getUUID("Entity").equals(actor.getUUID())){actor.setInvisible(true);actor.getNavigation().stop();return;}
        if(r.n.getString("Status").equals("CONVERTED")){actor.discard();return;}
        if(r.active()&&TycoonSouls.actorTick(p,r,actor))return;
        if(r.active()&&r.n.hasUUID("RescuingFarm")&&TycoonSoulFarms.actorTick(p,r,actor))return;
        if(r.active()&&TycoonStaffPlay.childTick(p,r,actor)){needs(r,20,true);return;}
        if(r.active()&&(TycoonWelcomeCake.tick(p,r,actor)||TycoonGifts.tick(p,r,actor)||TycoonMeals.carryToTable(p,r,actor)||TycoonMeals.tick(p,r,actor))){needs(r,20,true);return;}
        r.n.putLong("LastPosition",actor.blockPosition().asLong());if(!actor.getName().getString().equals(r.name()))actor.setCustomName(Component.literal(r.name()));if(TycoonVisits.visiting(r)){if(r.active())needs(r,20,true);if(TycoonVisits.actorTick(p,r,actor))return;}if(!r.active()){departureTick(p,h,r,actor);return;}
        if(actor.level()!=p.server.overworld()){actor.getNavigation().stop();return;}
        if(r.n.getString("Request").isEmpty())returnHeldBall(p,r,actor);
        // A recorded breaking point is an outcome, not a value that one ambient
        // comfort tick may pull back below100 before the decision is observed.
        if(r.need("Neglect")>=TycoonConfig.RUNAWAY.get()){depart(p,r,"RUNAWAY");h.reputation(-20);return;}
        TycoonRooms.Survey survey=TycoonRuntime.survey(p);int comfort=TycoonRooms.comfort(p,r,survey);if(r.n.getBoolean("DebugChild")&&r.n.getLong("DebugComfortUntil")>h.clock())comfort=r.n.getInt("DebugComfort");r.n.putInt("Comfort",comfort);needs(r,20,comfort>=55);long now=h.clock();
        if(r.bed()==null||!survey.beds().contains(r.bed())){if(!r.n.contains("InvalidBedSince")){r.n.putLong("InvalidBedSince",now);TycoonWorld.message(p,r.name()+" needs their bed and entrance restored. Existing residents are not deleted when furniture moves.");}if(now-r.n.getLong("InvalidBedSince")>12000)r.need("Neglect",r.need("Neglect")+.05);}else r.n.remove("InvalidBedSince");
        boolean critical=r.need("Hunger")<=1||r.need("Thirst")<=1;if(critical){int deprived=r.n.getInt("CriticalTicks")+20;r.n.putInt("CriticalTicks",deprived);actor.gesture(deprived>12000?6:5,25);if(deprived%1200==0)TycoonWorld.message(p,"Urgent: "+r.name()+" needs food/water immediately. Sustained deprivation is life-threatening.");if(deprived>=24000){depart(p,r,"DECEASED");h.reputation(-40);TycoonWorld.message(p,r.name()+" died after sustained deprivation. Placements suspended; no loot or rewards.");h.state.putLong("SuspendedUntil",now+72000);return;}if(deprived>12000){actor.getNavigation().stop();return;}}else r.n.putInt("CriticalTicks",Math.max(0,r.n.getInt("CriticalTicks")-40));
        if(r.need("Neglect")>=TycoonConfig.RUNAWAY.get()){depart(p,r,"RUNAWAY");h.reputation(-20);return;}
        if(now>=r.n.getLong("ArrivedAt")+24000&&r.need("Hunger")>35&&r.need("Thirst")>35&&r.need("Neglect")<50)h.milestone("resident_day_cared",50);
        if(r.n.getInt("ActionRemaining")>0){r.n.putInt("ActionRemaining",r.n.getInt("ActionRemaining")-20);actor.gesture(r.n.getInt("ActionGesture"),25);actor.getNavigation().stop();if(r.n.getInt("ActionRemaining")<=0)actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);return;}
        if(r.n.getString("Task").equals("ARRIVING")){boolean entered=r.n.getBoolean("ArrivalEntered");var destination=entered?TycoonRooms.approach(survey.reachable(),r.bed()):h.entrance()==null?null:TycoonWorld.landing(p.server.overworld(),h.entrance());if(move(actor,destination,.8)){if(!entered)r.n.putBoolean("ArrivalEntered",true);else{r.n.putString("Task","SETTLING_IN");actor.gesture(2,40);}}else if(now-r.n.getLong("ArrivedAt")>1200&&!r.n.getBoolean("ArrivalWarned")){r.n.putBoolean("ArrivalWarned",true);TycoonWorld.message(p,r.name()+" cannot reach their assigned room. Clear the entrance and stairs; the same resident will keep trying.");}return;}
        if(r.need("Thirst")<18){drink(p,h,r,actor,survey);return;}if(r.need("Hunger")<18){meal(p,h,r,actor,survey);return;}
        long daytime=p.server.overworld().getDayTime()%24000;if(daytime>13000&&daytime<23000||r.n.getBoolean("DebugChild")&&r.n.getLong("DebugSleepUntil")>now){var bed=r.bed();if(bed!=null&&(r.n.getString("Task").equals("SLEEPING")||move(actor,TycoonRooms.approach(survey.reachable(),bed),.7))){actor.getNavigation().stop();actor.setPos(bed.getX()+.5,bed.getY()+.57,bed.getZ()+.5);actor.gesture(4,25);r.n.putString("Task","SLEEPING");}return;}
        if(requestTick(p,h,r,actor))return;if(r.need("Hunger")<55){meal(p,h,r,actor,survey);return;}if(r.need("Thirst")<55){drink(p,h,r,actor,survey);return;}
        if(now>=r.n.getLong("NextRequest")&&now>=h.state.getLong("AttentionAfter")&&(p.level()==actor.level()&&p.distanceToSqr(actor)<100||TycoonWorkers.nearbyCarer(p,actor))){r.n.putString("Request",r.trait("Activity")>.6?"CATCH":r.trait("Sociability")>.55?"ATTENTION":"ITEM");r.n.putString("Wanted",r.trait("Curiosity")>.5?"minecraft:paper":r.n.getString("Favorite"));r.n.putLong("RequestExpires",now+1200);r.n.putBoolean("Accepted",false);h.state.putLong("AttentionAfter",now+2400);r.n.putLong("NextRequest",now+6000+(int)(r.trait("Patience")*6000));TycoonWorld.message(p,r.name()+" would like "+r.n.getString("Request").toLowerCase()+". Right-click to respond.");return;}
        if(incidentTick(p,h,r,actor,survey))return;
        r.n.putString("Task",r.trait("Sociability")>.6?"SOCIALIZING":r.trait("Curiosity")>.6?"EXPLORING":"PLAYING");
        if(r.trait("Sociability")>.6&&actor.getRandom().nextInt(3)==0){var friend=p.server.overworld().getEntitiesOfClass(TycoonNpc.class,actor.getBoundingBox().inflate(6),other->other!=actor&&!other.staff()&&TycoonWorld.owner(p).equals(other.owner)&&resident(other)!=null&&resident(other).active()).stream().findFirst();if(friend.isPresent()){actor.getLookControl().setLookAt(friend.get(),30,20);if(actor.distanceToSqr(friend.get())>4)actor.getNavigation().moveTo(friend.get(),.7);else actor.gesture(2,30);return;}}
        if(actor.getNavigation().isDone()&&actor.getRandom().nextInt(4)==0&&!survey.reachable().isEmpty()){BlockPos at=null;if(r.trait("Curiosity")>.6){var objects=survey.furniture().getOrDefault("orphan_plant",List.of());if(!objects.isEmpty())at=TycoonRooms.approach(survey.reachable(),objects.get(0));}if(at==null){var choices=new ArrayList<>(survey.reachable());at=choices.get(actor.getRandom().nextInt(choices.size()));}move(actor,at,.65+r.trait("Activity")*.3);}TycoonWorld.dirty(p);
    }
    public static boolean move(TycoonNpc npc,BlockPos at,double speed){if(at==null){npc.getNavigation().stop();return false;}if(npc.distanceToSqr(Vec3.atBottomCenterOf(at))<1.25){npc.getNavigation().stop();return true;}var path=npc.getNavigation().createPath(at,0);if(path!=null)npc.getNavigation().moveTo(path,speed);if(Boolean.getBoolean("coraline.tycoonPhaseOneCheck")&&!npc.staff()&&npc.tickCount%100==0){var r=resident(npc);com.mojang.logging.LogUtils.getLogger().info("TYCOON_RESIDENT_ROUTE task={} from={} to={} reachable={} done={} needs={}/{}",r==null?"unknown":r.n.getString("Task"),npc.position(),at,path!=null&&path.canReach(),npc.getNavigation().isDone(),r==null?-1:r.need("Hunger"),r==null?-1:r.need("Thirst"));}return false;}
    private static boolean incidentTick(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc actor,TycoonRooms.Survey survey){
        var n=r.n;if(!n.getString("Incident").isEmpty())return false;
        if(!n.contains("IncidentTarget")){if(h.clock()<n.getLong("NextIncident")||r.trait("Mischief")*.6+r.need("Neglect")/200<=.45)return false;for(String kind:List.of("toy_box","orphan_lamp","orphan_rug")){var objects=survey.furniture().getOrDefault(kind,List.of());if(!objects.isEmpty()){n.putLong("IncidentTarget",objects.get(0).asLong());n.putLong("IncidentStarted",h.clock());break;}}if(!n.contains("IncidentTarget")){n.putLong("NextIncident",h.clock()+12000);return false;}}
        var at=BlockPos.of(n.getLong("IncidentTarget"));var l=p.server.overworld();if(h.clock()-n.getLong("IncidentStarted")>1200||!(l.getBlockEntity(at) instanceof TycoonBlockEntity be)||!h.owner.equals(be.owner)||be.getBlockState().getValue(TycoonBlock.BROKEN)){n.remove("IncidentTarget");n.putLong("NextIncident",h.clock()+12000);return false;}
        n.putString("Task","PLAYING_WITH_FURNITURE");if(!move(actor,TycoonRooms.approach(survey.reachable(),at),.85))return true;
        String kind=((TycoonBlock)l.getBlockState(at).getBlock()).kind;l.setBlock(at,l.getBlockState(at).setValue(TycoonBlock.BROKEN,true),3);n.putString("Incident",kind.equals("orphan_rug")?"Spilled a drink on the rug":kind.equals("toy_box")?"Broke a toy":"Knocked the lamp over");n.putLong("IncidentAt",at.asLong());n.remove("IncidentTarget");n.putLong("NextIncident",h.clock()+12000);actor.gesture(5,60);TycoonWorld.message(p,r.name()+": "+n.getString("Incident")+". Right-click to forgive or assign cleanup.");return true;
    }
    private static void meal(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc actor,TycoonRooms.Survey survey){TycoonMeals.overworld(p,h,r,actor,survey);}
    private static BlockPos tableFor(TycoonData.Home h,TycoonData.Resident r,List<BlockPos> tables){var used=new HashSet<Long>();for(var other:h.residents.values())if(!other.id.equals(r.id)&&other.active()&&other.n.contains("DiningClaim")&&other.n.getLong("DiningClaimUntil")>h.clock())used.add(other.n.getLong("DiningClaim"));var own=r.n.contains("DiningClaim")?BlockPos.of(r.n.getLong("DiningClaim")):null;var table=own!=null&&tables.contains(own)?own:tables.stream().filter(at->!used.contains(at.asLong())).findFirst().orElse(null);if(table!=null){r.n.putLong("DiningClaim",table.asLong());r.n.putLong("DiningClaimUntil",h.clock()+100);}return table;}
    private static void drink(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc actor,TycoonRooms.Survey survey){r.n.putString("Task","SEEKING_WATER");var stations=survey.furniture().getOrDefault("water_station",List.of());if(stations.isEmpty())return;var at=stations.get(0);if(!move(actor,TycoonRooms.approach(survey.reachable(),at),.8))return;if(!r.n.contains("WaterRequest")){r.n.putLong("WaterRequest",h.clock());if(p.distanceToSqr(actor)<144)TycoonWorld.message(p,r.name()+" would like a drink. Hand them a water bottle.");}if(h.clock()-r.n.getLong("WaterRequest")<200+600*r.trait("Patience")||h.clock()<r.n.getLong("WaterRetry"))return;var be=(TycoonBlockEntity)p.server.overworld().getBlockEntity(at);if(be.water>0){be.water--;be.setChanged();r.need("Thirst",r.need("Thirst")+45);r.need("Neglect",r.need("Neglect")+.2);r.n.remove("WaterRequest");animate(r,actor,7,40);}else{r.need("Neglect",r.need("Neglect")+.5);r.n.putLong("WaterRetry",h.clock()+400);}}
    public static void feed(TycoonData.Resident r,ItemStack food,boolean served){TycoonMeals.applyCare(r,food,served);}
    private static void animate(TycoonData.Resident r,TycoonNpc a,int gesture,int ticks){r.n.putInt("ActionGesture",gesture);r.n.putInt("ActionRemaining",ticks);a.gesture(gesture,ticks);}
    public static boolean serve(ServerPlayer p,TycoonNpc actor){var r=resident(actor);if(r==null||!r.active()||!TycoonWorld.owner(p).equals(actor.owner)||actor.level()!=p.level()||actor.distanceToSqr(p)>25)return false;var item=p.getMainHandItem();
        if(r.n.getBoolean("Accepted")&&r.n.getString("Request").equals("ITEM")&&!item.isEmpty()&&net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(item.getItem()).toString().equals(r.n.getString("Wanted"))){item.shrink(1);complete(p,r);return true;}
        if(TycoonBlockEntity.food(item)&&TycoonMeals.manual(p,r,actor))return true;if(item.is(Items.POTION)&&net.minecraft.world.item.alchemy.PotionUtils.getPotion(item)==net.minecraft.world.item.alchemy.Potions.WATER&&r.need("Thirst")<90){if(item.getCount()==1)p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.GLASS_BOTTLE));else{if(p.getInventory().getFreeSlot()<0)return false;item.shrink(1);p.getInventory().add(new ItemStack(Items.GLASS_BOTTLE));}r.need("Thirst",r.need("Thirst")+50);r.need("Neglect",r.need("Neglect")-3);r.n.remove("WaterRequest");animate(r,actor,7,40);TycoonWorld.dirty(p);return true;}return false;}
    public static void serveAt(ServerPlayer p,BlockPos table){var h=TycoonWorld.home(p);for(var r:h.residents.values())if(r.active()&&r.n.hasUUID("Entity")&&p.server.overworld().getEntity(r.n.getUUID("Entity")) instanceof TycoonNpc a&&a.distanceToSqr(table.getCenter())<9&&serve(p,a))return;TycoonWorld.message(p,"Approach a waiting resident with food or a water bottle.");}
    private static boolean requestTick(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc actor){var n=r.n;if(n.getString("Request").isEmpty())return false;long now=h.clock();if(now>n.getLong("RequestExpires")){r.need("Neglect",r.need("Neglect")+2+r.trait("Sensitivity")*2);closeRequest(r);return false;}if(!n.getBoolean("Accepted"))return false;r.n.putString("Task","REQUEST_"+n.getString("Request"));if(n.getString("Request").equals("ATTENTION")){if(p.level()==actor.level()&&p.distanceToSqr(actor)<16){n.putInt("AttentionTicks",n.getInt("AttentionTicks")+20);actor.getLookControl().setLookAt(p,30,30);actor.gesture(2,25);if(n.getInt("AttentionTicks")>=200)complete(p,r);}return true;}if(n.getString("Request").equals("CATCH")){catchTick(p,h,r,actor);return true;}return false;}
    private static void closeRequest(TycoonData.Resident r){for(String key:List.of("Request","Accepted","AttentionTicks","Passes","CatchStart"))r.n.remove(key);}
    private static void returnHeldBall(ServerPlayer p,TycoonData.Resident r,TycoonNpc actor){if(!r.n.contains("HeldBall"))return;var item=ItemStack.of(r.n.getCompound("HeldBall"));var ball=new ItemEntity(p.server.overworld(),actor.getX(),actor.getY()+.5,actor.getZ(),item);ball.setPickUpDelay(10);if(p.server.overworld().addFreshEntity(ball))r.n.remove("HeldBall");}
    private static void complete(ServerPlayer p,TycoonData.Resident r){if(r.n.getString("Request").equals("CATCH")){r.n.putInt("LastCatchPasses",r.n.getInt("Passes"));r.n.putLong("LastCatchTicks",TycoonWorld.home(p).clock()-r.n.getLong("CatchStart"));}r.need("Neglect",r.need("Neglect")-6);closeRequest(r);TycoonWorld.message(p,r.name()+" enjoyed that. Request complete.");TycoonWorld.dirty(p);}
    static void staffComplete(ServerPlayer p,TycoonData.Resident r){complete(p,r);}
    public static String respond(ServerPlayer p,UUID id,String action){var h=TycoonWorld.home(p);var r=h.residents.get(id);if(r==null||!r.active()||!r.n.hasUUID("Entity")||!(p.server.overworld().getEntity(r.n.getUUID("Entity")) instanceof TycoonNpc actor)||p.level()!=actor.level()||p.distanceToSqr(actor)>25)return "Resident is not within reach.";var n=r.n;
        switch(action){case "accept"->{if(n.getString("Request").isEmpty())return "No pending request.";n.putBoolean("Accepted",true);n.putLong("RequestExpires",h.clock()+2400);if(n.getString("Request").equals("CATCH"))n.putLong("CatchStart",h.clock());return "Accepted. "+(n.getString("Request").equals("CATCH")?"Use a real Play Ball; throw it toward your partner and catch their returns.":n.getString("Request").equals("ITEM")?"Bring "+n.getString("Wanted"):"Stay nearby and spend time together.");}
        case "decline"->{if(!n.getString("Request").isEmpty()){r.need("Neglect",r.need("Neglect")+1+r.trait("Sensitivity")*2);actor.gesture(5,50);closeRequest(r);}}
        case "give"->{if(!n.getBoolean("Accepted")||!n.getString("Request").equals("ITEM"))return "Accept the item request first.";var item=p.getMainHandItem();if(!net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(item.getItem()).toString().equals(n.getString("Wanted")))return "Hold the requested item.";item.shrink(1);complete(p,r);}
        case "forgive","punish"->{if(n.getString("Incident").isEmpty())return "No incident to resolve.";r.need("Neglect",r.need("Neglect")+(action.equals("forgive")?-3:2+r.trait("Sensitivity")*2));if(n.contains("IncidentAt")){var at=BlockPos.of(n.getLong("IncidentAt"));if(p.server.overworld().getBlockEntity(at) instanceof TycoonBlockEntity be&&TycoonWorld.owner(p).equals(be.owner))p.server.overworld().setBlock(at,be.getBlockState().setValue(TycoonBlock.BROKEN,false),3);}n.remove("Incident");if(action.equals("punish"))animate(r,actor,5,200);}
        default->{return "Unknown resident action.";}}
        TycoonWorld.dirty(p);return "Response recorded.";
    }
    public static void throwBall(ServerPlayer p){var h=TycoonWorld.home(p);for(var r:h.residents.values())if(r.active()&&r.n.getBoolean("Accepted")&&r.n.getString("Request").equals("CATCH")&&!r.n.hasUUID("Ball")&&!r.n.contains("HeldBall")&&r.n.hasUUID("Entity")&&p.serverLevel().getEntity(r.n.getUUID("Entity")) instanceof TycoonNpc actor&&p.distanceToSqr(actor)<144){var ball=p.getMainHandItem();if(!ball.is(TycoonContent.BALL.get()))return;var copy=ball.split(1);copy.getOrCreateTag().putUUID("CatchOwner",p.getUUID());copy.getTag().putUUID("CatchHousehold",h.owner);copy.getTag().putUUID("CatchResident",r.id);var projectile=new ItemEntity(p.serverLevel(),p.getX(),p.getEyeY()-.2,p.getZ(),copy);projectile.setPickUpDelay(10);var delta=actor.position().add(0,1,0).subtract(projectile.position());projectile.setDeltaMovement(delta.scale(.12).add(0,.18,0));if(p.serverLevel().addFreshEntity(projectile)){r.n.putUUID("Ball",projectile.getUUID());r.n.putBoolean("BallReturning",false);r.n.putLong("BallThrown",h.clock());}else p.getInventory().add(copy);TycoonWorld.dirty(p);return;}}
    private static void catchTick(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc actor){var n=r.n;if(n.hasUUID("Ball")){var e=p.server.overworld().getEntity(n.getUUID("Ball"));if(e instanceof ItemEntity ball&&!n.getBoolean("BallReturning")){actor.getNavigation().moveTo(ball,.8);if(actor.distanceToSqr(ball)<2.5){n.put("HeldBall",ball.getItem().save(new CompoundTag()));ball.discard();n.remove("Ball");n.putLong("ReturnBallAt",h.clock()+20);actor.gesture(8,30);}}else if(h.clock()-n.getLong("BallThrown")>200){n.remove("Ball");TycoonWorld.message(p,"Retrieve the ball and throw again.");}}
        if(n.contains("HeldBall")&&h.clock()>=n.getLong("ReturnBallAt")){var item=ItemStack.of(n.getCompound("HeldBall"));var ball=new ItemEntity(p.server.overworld(),actor.getX(),actor.getY()+1.1,actor.getZ(),item);var d=p.position().add(0,.6,0).subtract(ball.position());ball.setDeltaMovement(d.scale(.1).add(0,.18,0));ball.setPickUpDelay(8);if(p.server.overworld().addFreshEntity(ball)){n.remove("HeldBall");n.putUUID("Ball",ball.getUUID());n.putBoolean("BallReturning",true);n.putLong("BallThrown",h.clock());actor.gesture(9,30);}}
        if(n.getInt("Passes")>=3&&h.clock()-n.getLong("CatchStart")>=200)complete(p,r);
    }
    public static void ballPickup(ServerPlayer p,ItemEntity ball){var tag=ball.getItem().getTag();if(tag==null||!tag.hasUUID("CatchOwner")||!p.getUUID().equals(tag.getUUID("CatchOwner"))||!tag.hasUUID("CatchResident"))return;TycoonScope.run(p,tag.hasUUID("CatchHousehold")?tag.getUUID("CatchHousehold"):p.getUUID(),()->{var r=TycoonWorld.home(p).residents.get(tag.getUUID("CatchResident"));if(r!=null&&r.n.hasUUID("Ball")&&ball.getUUID().equals(r.n.getUUID("Ball"))&&r.n.getBoolean("BallReturning")&&r.n.getBoolean("Accepted")){r.n.putInt("Passes",r.n.getInt("Passes")+1);r.n.remove("Ball");TycoonWorld.dirty(p);}});}
    public static void depart(ServerPlayer p,TycoonData.Resident r,String outcome){if(!r.active())return;r.n.putString("Status",outcome);r.n.putLong("OutcomeAt",TycoonWorld.home(p).clock());r.n.putString("Task","LEAVING");r.n.remove("Bed");closeRequest(r);TycoonWorld.message(p,r.name()+": "+outcome.replace('_',' ')+". This identity and outcome remain recorded.");TycoonWorld.dirty(p);}
    private static boolean visible(ServerPlayer p,TycoonNpc a){for(var viewer:p.server.getPlayerList().getPlayers())if(viewer.level()==a.level()&&viewer.distanceToSqr(a)<128*128&&viewer.getLookAngle().dot(a.getEyePosition().subtract(viewer.getEyePosition()).normalize())>0&&viewer.hasLineOfSight(a))return true;return false;}
    private static void departureTick(ServerPlayer p,TycoonData.Home h,TycoonData.Resident r,TycoonNpc a){boolean deceased=r.n.getString("Status").equals("DECEASED");a.gesture(deceased?6:5,25);returnHeldBall(p,r,a);var entrance=h.entrance();if(deceased)a.getNavigation().stop();else if(entrance!=null){var target=TycoonWorld.landing(p.server.overworld(),entrance.south(10));if(target!=null)a.getNavigation().moveTo(target.getX()+.5,target.getY(),target.getZ()+.5,.7);}if(!visible(p,a)&&h.clock()-r.n.getLong("OutcomeAt")>100){a.discard();r.n.putBoolean("Departed",true);TycoonWorld.dirty(p);}}
    private static void staffTick(ServerPlayer p,TycoonNpc a){var h=TycoonWorld.home(p);if(a.getPersistentData().getBoolean("Leaving")){if(!h.state.hasUUID("Inspector")||!h.state.getUUID("Inspector").equals(a.getUUID())){a.discard();return;}if(h.entrance()!=null){var at=TycoonWorld.landing(p.server.overworld(),h.entrance().south(12));if(at!=null)a.getNavigation().moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,.8);}if(!visible(p,a)&&h.entrance()!=null&&a.distanceToSqr(h.entrance().getCenter())>36){TycoonAgency.retireInspector(p,a);}}else if(!a.getPersistentData().getBoolean("Inspector")&&h.state.contains("Agency")){var c=BlockPos.of(h.state.getLong("Agency"));if(a.getRandom().nextInt(5)==0){var at=c.offset(-4+a.getRandom().nextInt(4),1,-3+a.getRandom().nextInt(5));a.getNavigation().moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,.6);}}}
}
